import useFetch from './hooks/useFetch.js';
function Quotes () {

    const { data }  = useFetch(
      JSON.stringify(data[0].q)
    );

    let quote = JSON.stringify(data[0].q);

    return (
        <div className="width-fit bg-white-opacity-30">
            <p>{quote}</p>
        </div>
    )
}

export default Quotes
